      othersPinAgent: 'Canvassed by {agent}',
      guideTitle: 'Canvassing: how we do it',
      guideIntro: 'The flyer, the pitch, the techniques that work, and the Fairide attitude.',
      guideShow: 'Show the guide',
      guideHide: 'Hide the guide',
      flyerTitle: 'The Fairide flyer: always with you',
      flyerText: 'Print a stack before each round. Leave one at every business, even when it is a no: it is what stays on the counter.',
      flyerOpen: 'Open / print the flyer',
      flyerDownload: 'Download (PDF)',
      guideRepTitle: 'You represent Fairide',
      guideRepText: 'Smiling, polite, on time, honest: every business owner remembers you before remembering the app. We never push, never badmouth other platforms, never promise anything that is not on the flyer. Unsure about something? Say "I will check and get back to you", and do it.',
      guideBeforeTitle: 'Before you leave',
      guideBefore1: 'A stack of flyers, a pen, your charged phone with the Fairide app open (to show a page and a menu online).',
      guideBefore2: 'Pick your area in "Areas" and take it: nobody else will come after you.',
      guideBefore3: 'The right time: between 2:30 and 5:30 pm, or in the morning before 11:30. Never during the rush.',
      guideBefore4: 'Ask for the owner or the manager. Not there? Note their first name and when they are in, and come back.',
      guidePitchTitle: 'The 30-second pitch',
      guidePitchText: '"Hello, I am [first name], from Fairide, the new Brussels app for delivery, takeaway and bookings. One rule: 10% commission, only on delivery and online payment. Bookings and takeaway paid at your place: 0%. On a €40 order you keep €36 instead of €28. Can I show you in two minutes?"',
      guidePitch1: 'One sentence, one number, one question. Then stop talking and listen.',
      guidePitch2: 'Show the flyer: the €28 / €36 comparison speaks for itself.',
      guidePitch3: 'Free version first (bookings + takeaway paid on site, €0): nobody says no to free.',
      guidePitch4: 'Terminal free for the first 50 restaurants signed up before 5 October, then an €80 deposit: that is the reason to sign now.',
      guideTechTitle: 'Techniques that work',
      guideTech1: 'Ask questions before selling: "Are you on Uber Eats? What does it cost you per month?" The owner convinces themselves.',
      guideTech2: 'Talk about their money, not our features: +€8 per order, €800 a month for 100 orders.',
      guideTech3: 'Sign them up on the spot, with them, in 5 minutes: account created = your €20 bonus earned. Then link your record to the business in Sales.',
      guideTech4: 'Their menu? Nothing to do: Fairide creates it from their website, Uber Eats or a photo of the menu. Say it clearly.',
      guideTech5: 'Log everything in Sales as soon as you leave: stage, what they said, their next availability. An unlogged visit is a lost visit.',
      guideTech6: 'An unsigned "yes" does not exist: set a precise appointment ("Thursday 3 pm, I come back with the terminal?").',
      guideNoTitle: 'If it is a no, no problem',
      guideNo1: 'Stay professional and friendly: "No worries, thanks for your time."',
      guideNo2: 'Leave the flyer on the counter: "I leave it with you, everything is on it, with our number."',
      guideNo3: 'Wish them a pleasant day, and leave.',
      guideNo4: 'In Sales: stage "Later", a note on why it was a no, and a next action the week after.',
      guideNo5: 'Come back the following week, without pushing: "I was around, did you have time to think about it?" Many "no"s become "yes" on the second visit.',
      guideYesTitle: 'If it is a yes',
      guideYes1: 'Create the account with them on the spot (fairide.be › Sign up › Restaurant): e-mail, phone, address.',
      guideYes2: 'Explain the three dates: app on 6 October, bookings and takeaway on the 10th, delivery on the 20th.',
      guideYes3: 'Tell them what happens next: Fairide creates their menu, they check it, the team validates them, then the terminal is installed with them in 30 minutes.',
      guideYes4: 'Link your record to the business in Sales and move it to "Signed up on Fairide": your bonus is counted.',
